from fractions import Fraction

def signed(n):
    # the text " + n" or " - |n|", for a term written after another
    if n < 0:
        return f" - {-n}"
    return f" + {n}"

def solve(kind, nums):
    if kind == "multiply":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        return f"multiply: {[a * c, a * d + b * c, b * d]}"
    if kind == "remainder":
        c = nums[0]
        row = [nums[1]]
        for k in range(2, len(nums)):
            row.append(nums[k] + c * row[len(row) - 1])
        return f"remainder: p({c}) = {row[len(row) - 1]}"
    if kind == "ipower":
        names = ["1", "i", "-1", "-i"]
        return f"ipower: i^{nums[0]} = {names[nums[0] % 4]}"
    if kind == "roots":
        a, b, c = nums[0], nums[1], nums[2]
        D = b * b - 4 * a * c
        if D > 0:
            return f"roots: D = {D}, two real roots"
        if D == 0:
            return f"roots: D = {D}, one real root"
        return f"roots: D = {D}, no real roots"
    if kind == "power":
        a, m, n = nums[0], nums[1], nums[2]
        e = Fraction(m, n)
        r = 0
        while r ** e.denominator < a:
            r = r + 1
        return f"power: {a}^({m}/{n}) = {Fraction(r) ** e.numerator}"
    b, c = nums[0], nums[1]
    bound = abs(b) + abs(c)
    for p in range(-bound, bound + 1):
        q = b - p
        if p <= q and p * q == c:
            return f"factor: (x{signed(p)})(x{signed(q)})"
    return "factor: prime"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))

