import math
from fractions import Fraction

def quadratic(a, b, c):
    # the roots of ax^2 + bx + c = 0, a > 0, by the formula: exact when D is a perfect square
    D = b * b - 4 * a * c
    s = math.isqrt(abs(D))
    if s * s == abs(D):
        p, q = Fraction(-b, 2 * a), Fraction(s, 2 * a)
        if D < 0:
            return D, f"x = {p} + {q}i or x = {p} - {q}i"
        if D == 0:
            return D, f"x = {p} twice"
        return D, f"x = {p - q} or x = {p + q}"
    p, q = -b / (2 * a), math.sqrt(abs(D)) / (2 * a)
    if D < 0:
        return D, f"x = {p:.4f} + {q:.4f}i or x = {p:.4f} - {q:.4f}i"
    return D, f"x = {p - q:.4f} or x = {p + q:.4f}"

def synthetic(p, c):
    # divide p, highest power first, by x - c: the quotient and the remainder
    row = [p[0]]
    for k in range(1, len(p)):
        row.append(p[k] + c * row[k - 1])
    q = []
    for k in range(len(row) - 1):
        q.append(row[k])
    return q, row[len(row) - 1]

def pair(B, C):
    # the roots of x^2 + Bx + C = 0 by factoring: u + v = B and uv = C
    for u in range(-abs(B) - abs(C), abs(B) + abs(C) + 1):
        v = B - u
        if u == v and u * u == C:
            return [-u]
        if u < v and u * v == C:
            return [-v, -u]
    return []

def solve(kind, nums):
    if kind == "cubic":
        # x^3 + ..., highest power first: try c = 1, -1, 2, -2, ... dividing the constant
        a0 = nums[3]
        for k in range(1, abs(a0) + 1):
            for c in [k, -k]:
                q, r = synthetic(nums, c)
                if a0 % k == 0 and r == 0:
                    print(f"  p({c}) = 0, so divide by x - ({c}): quotient {q}")
                    print(f"  roots: x = {c}, and from the quotient {quadratic(q[0], q[1], q[2])[1]}")
                    return
    elif kind == "quadratic":
        D, roots = quadratic(nums[0], nums[1], nums[2])
        print(f"  D = {D}: {roots}")
    elif kind == "radical":
        p, q, s = nums[0], nums[1], nums[2]
        print(f"  sqrt(px + q) = x + s, squared: x^2 + ({2 * s - p})x + ({s * s - q}) = 0")
        for x in pair(2 * s - p, s * s - q):
            verdict = "at least 0, a solution" if x + s >= 0 else "negative, extraneous"
            print(f"  x = {x}: the right side is {x + s}, {verdict}")
    elif kind == "rational":
        a, p, c = nums[0], nums[1], nums[2]
        print(f"  ax/(x - p) = c/(x - p) + x, times x - ({p}): x^2 + ({-(p + a)})x + ({c}) = 0")
        for x in pair(-(p + a), c):
            verdict = "excluded, extraneous" if x == p else "not excluded, a solution"
            print(f"  x = {x}: {verdict}")

problems = [
    ("Example 2 · x^3 + 2x^2 - 5x - 6 = 0", "cubic", [1, 2, -5, -6]),
    ("Example 4 · x^2 + 6x + 13 = 0", "quadratic", [1, 6, 13]),
    ("Example 6 · sqrt(x + 10) = x - 2", "radical", [1, 10, -2]),
    ("Example 3 · x^3 - 3x^2 - 2x + 4 = 0", "cubic", [1, -3, -2, 4]),
    ("Example 5 · 2x/(x - 4) = 8/(x - 4) + x", "rational", [2, 4, 8]),
    ("Example 9 · x^2 + 8x + 3 = 0", "quadratic", [1, 8, 3]),
    ("A double root: 4x^2 - 12x + 9 = 0", "quadratic", [4, -12, 9]),
    ("Both good: sqrt(5x + 1) = x + 1", "radical", [5, 1, 1]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

