import math
from fractions import Fraction

def text(v):
    # a whole number as it is, anything else to 4 decimals
    # (int() drops any part after the point, so v == int(v) only when v is whole)
    if v == int(v):
        return f"{int(v)}"
    return f"{v:.4f}"

def roots(a, b, c):
    D = b * b - 4 * a * c
    s = math.isqrt(D)
    if s * s == D:
        r1, r2 = Fraction(-b - s, 2 * a), Fraction(-b + s, 2 * a)
    else:
        r1, r2 = (-b - math.sqrt(D)) / (2 * a), (-b + math.sqrt(D)) / (2 * a)
    if r1 > r2:
        r1, r2 = r2, r1
    return r1, r2

def solve(kind, nums):
    if kind == "fall":
        return f"fall from {nums[0]} m: t = {text(roots(5, 0, -nums[0])[1])} s"
    if kind == "throw":
        v, h0 = nums[0], nums[1]
        return f"throw at {v} m/s from {h0} m: t = {text(roots(-5, v, h0)[1])} s"
    if kind == "rectangle":
        d, A = nums[0], nums[1]
        w = roots(1, d, -A)[1]
        return f"rectangle: {text(w)} m by {text(w + d)} m"
    if kind == "together":
        a, b = nums[0], nums[1]
        return f"together: {text(Fraction(a * b, a + b))} h"
    if kind == "sides":
        x1, x2 = roots(1, -(nums[0] // 2), nums[1])
        return f"sides: {text(x1)} m by {text(x2)} m"
    return f"pendulum: L = {text(Fraction(nums[0], 2) ** 2)} m"

n = int(input())
for i in range(n):
    kind = input()
    count = int(input())
    nums = []
    for j in range(count):
        nums.append(int(input()))
    print(solve(kind, nums))

