import math
from fractions import Fraction

def synthetic(p, c):
    # divide p, highest power first, by x - c: the quotient and the remainder
    row = [p[0]]
    for k in range(1, len(p)):
        row.append(p[k] + c * row[k - 1])
    q = []
    for k in range(len(row) - 1):
        q.append(row[k])
    return q, row[len(row) - 1]

def divide_out(p):
    # the first root r/s, r dividing the constant term and s the leading coefficient
    for r in range(1, abs(p[len(p) - 1]) + 1):
        for s in range(1, abs(p[0]) + 1):
            for v in [Fraction(r, s), Fraction(-r, s)]:
                q, rem = synthetic(p, v)
                if p[len(p) - 1] % r == 0 and p[0] % s == 0 and rem == 0:
                    whole = []
                    for a in q:
                        whole.append(int(a))
                    return v, whole

def quadratic(a, b, c):
    # both roots of ax^2 + bx + c = 0, a > 0, as text: exact when D is a perfect square
    D = b * b - 4 * a * c
    s = math.isqrt(abs(D))
    if s * s != abs(D):
        p, q = -b / (2 * a), math.sqrt(abs(D)) / (2 * a)
        if D < 0:
            return [f"{p:.4f} + {q:.4f}i", f"{p:.4f} - {q:.4f}i"]
        return [f"{p - q:.4f}", f"{p + q:.4f}"]
    p, q = Fraction(-b, 2 * a), Fraction(s, 2 * a)
    if D < 0 and p == 0:
        return [f"{q}i", f"-{q}i"]
    if D < 0:
        return [f"{p} + {q}i", f"{p} - {q}i"]
    return [f"{p - q}", f"{p + q}"]

def solve(kind, nums):
    if kind == "allroots":
        p, roots = nums, []
        while len(p) > 3:
            v, p = divide_out(p)
            roots.append(f"{v}")
            print(f"  p({v}) = 0: divide by x - ({v}), quotient {p}")
        for t in quadratic(p[0], p[1], p[2]):
            roots.append(t)
        print(f"  the quadratic {p} by the formula: {roots[len(roots) - 2]} and {roots[len(roots) - 1]}")
        print(f"  every root: {', '.join(roots)}")
    elif kind == "product":
        p, q, k = nums[0], nums[1], nums[2]
        B, C = -(p + q), p * q - k
        print(f"  multiply out, move {k}: x^2 + ({B})x + ({C}) = 0")
        print(f"  x = {' or x = '.join(quadratic(1, B, C))}")
    elif kind == "onek":
        m = 4 * nums[0] * nums[1]
        s = math.isqrt(abs(m))
        print(f"  one root when D = k^2 - 4ac = 0, so k^2 = 4ac = {m}")
        if m < 0:
            print("  no real k: a square is never negative")
        elif s * s == m:
            print(f"  k = -{s} or k = {s}")
        else:
            print(f"  k = -{math.sqrt(m):.4f} or k = {math.sqrt(m):.4f}")

problems = [
    ("Example 3 · 3x^3 - 4x^2 - 5x + 2 = 0", "allroots", [3, -4, -5, 2]),
    ("Example 6 · (x - 3)(x + 1) = 5", "product", [3, -1, 5]),
    ("Example 2 · x^4 - 81 = 0", "allroots", [1, 0, 0, 0, -81]),
    ("Example 7 · x^2 + kx + 9 = 0", "onek", [1, 9]),
    ("Example 1 · x^4 - 5x^2 + 4 = 0", "allroots", [1, 0, -5, 0, 4]),
    ("No real k: 2x^2 + kx - 8 = 0", "onek", [2, -8]),
]
for label, kind, nums in problems:
    print(label)
    solve(kind, nums)

